input.command:
kill %1 2>/dev/null; pkill -f 'find /' 2>/dev/null; cd /workspace
cat > /tmp/init.sql <<'EOF'
INSTALL spatial; LOAD spatial;
INSTALL httpfs; LOAD httpfs;
SET http_keep_alive=true;
SET http_timeout=300000;
EOF
duckdb /workspace/work.db < /tmp/init.sql 2>&1 | head
echo "=== FIELD schema/sample ==="
duckdb /workspace/work.db <<'EOF' 2>&1 | head -60
LOAD spatial; LOAD httpfs;
DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet') LIMIT 1;
EOF

cd /workspace
duckdb -csv /workspace/work.db <<'EOF' 2>&1 | head -80
LOAD spatial; LOAD httpfs;
SELECT name, type FROM parquet_schema('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet');
SELECT '--- FIELD row count (q04) ---' AS x;
SELECT count(*) AS n_rows FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet');
EOF

cd /workspace
duckdb -csv /workspace/work.db <<'EOF' 2>&1 | head -60
LOAD spatial; LOAD httpfs;
SELECT name, type FROM parquet_schema('https://data.source.coop/tristangruppwri/cadastral/Brazil_CAR_AREA_IMOVEL.parquet') WHERE name<>'duckdb_schema';
EOF

cd /workspace
time duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -30
LOAD spatial; LOAD httpfs; SET http_timeout=600000;
-- load the input list
CREATE OR REPLACE TABLE list AS SELECT * FROM read_csv('lists/goias-sample.csv', header=true);
SELECT count(*) list_rows, count(distinct cod_imovel) list_ids FROM list;
-- materialize listed parcels from CAR (remote filtered scan)
CREATE OR REPLACE TABLE parcels_raw AS
SELECT cod_imovel, num_area, municipio, cod_estado,
       ST_GeomFromWKB(geometry) AS geom
FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/Brazil_CAR_AREA_IMOVEL.parquet')
WHERE cod_imovel IN (SELECT cod_imovel FROM list);
SELECT count(*) AS parcel_rows, count(distinct cod_imovel) AS parcel_ids FROM parcels_raw;
EOF

cd /workspace
time duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -20
LOAD spatial; LOAD httpfs; SET http_timeout=600000;
CREATE OR REPLACE TABLE parcels_raw AS
SELECT cod_imovel, num_area, municipio, cod_estado, geometry AS geom
FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/Brazil_CAR_AREA_IMOVEL.parquet')
WHERE cod_imovel IN (SELECT cod_imovel FROM list);
SELECT count(*) AS parcel_rows, count(distinct cod_imovel) AS parcel_ids FROM parcels_raw;
EOF

cd /workspace
time duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -10
LOAD spatial; LOAD httpfs; SET http_timeout=600000;
SELECT count(*) AS n_rows, count(distinct cod_imovel) AS n_distinct_ids
FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/Brazil_CAR_AREA_IMOVEL.parquet');
EOF

cd /workspace
duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -20
LOAD spatial; LOAD httpfs;
CREATE OR REPLACE TABLE facilities AS SELECT * FROM read_parquet('/workspace/data/BR_facilities.parquet');
SELECT tier, count(*) AS n FROM facilities GROUP BY tier ORDER BY tier;
SELECT '--- total ---' t; SELECT count(*) FROM facilities;
SELECT '--- entity_kind ---' t; SELECT entity_kind, tier, count(*) n FROM facilities GROUP BY 1,2 ORDER BY 1,2;
EOF

cd /workspace
duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -40
LOAD spatial;
SELECT '--- CAR municipio ---' t;
SELECT municipio, count(*) n FROM parcels_raw GROUP BY 1 ORDER BY 1;
SELECT '--- under 1ha ---' t;
SELECT count(*) FROM parcels_raw WHERE num_area < 1;
SELECT '--- num_area summary ---' t;
SELECT min(num_area), max(num_area), avg(num_area) FROM parcels_raw;
SELECT '--- list municipio vs code ---' t;
SELECT substr(cod_imovel,4,7) AS ibge, municipio, count(*) FROM parcels_raw GROUP BY 1,2 ORDER BY 1;
EOF

cd /workspace
time duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -30
LOAD spatial;
-- overall bounding envelope of listed parcels
CREATE OR REPLACE TABLE env AS SELECT ST_Envelope(ST_Union_Agg(geom)) AS env FROM parcels_raw;
-- q08: fields intersecting the bounding envelope
SELECT count(*) AS n_fields_in_envelope
FROM fields f, env e WHERE ST_Intersects(f.geom, e.env);
EOF

cd /workspace
time duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -60
LOAD spatial;
CREATE OR REPLACE TABLE matched AS
SELECT m.field_id, m.primary_cod AS cod_imovel,
       m.single_frac, m.union_frac, m.by_primary, m.by_aggregate,
       f.mbmode24, f.field_area,
       ST_Area_Spheroid(f.geom)/10000.0 AS field_ha,
       f.mode_year, f.firstyear, f.firstyearmajority,
       f.deforestarea0104, f.deforestarea0509, f.deforestarea1014, f.deforestarea1520, f.deforestarea2124
FROM match m JOIN fields f ON f.Id=m.field_id
WHERE m.by_primary OR m.by_aggregate;
SELECT count(*) FROM matched;
-- q11
SELECT '--- q11 ---' t;
SELECT min(single_frac) AS min_single, avg(single_frac) AS avg_single, avg(union_frac) AS avg_union FROM matched;
-- q12 excluded = fields intersecting a listed parcel but failing both
SELECT '--- q12 ---' t;
SELECT (SELECT count(distinct field_id) FROM fp) - (SELECT count(*) FROM matched) AS n_excluded;
-- q14 total matched-field hectares
SELECT '--- q14 ---' t;
SELECT sum(field_ha) AS matched_field_ha FROM matched;
-- q13 top 10 cadasters by matched-field count
SELECT '--- q13 ---' t;
SELECT cod_imovel, count(*) n_fields FROM matched GROUP BY 1 ORDER BY n_fields DESC, cod_imovel ASC LIMIT 10;
EOF

cd /workspace
duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -20
LOAD spatial; SET geometry_always_xy=true;
SELECT ST_Area_Spheroid(geom)/10000.0 AS ha_xy FROM matched LIMIT 1;
-- recompute field_ha correctly
ALTER TABLE matched DROP COLUMN field_ha;
ALTER TABLE matched ADD COLUMN field_ha DOUBLE;
UPDATE matched SET field_ha = ST_Area_Spheroid(geom)/10000.0
FROM (SELECT Id, geom FROM fields) f WHERE f.Id = matched.field_id;
SELECT sum(field_ha) AS total_ha FROM matched;
EOF

cd /workspace
duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -20
LOAD spatial;
-- compare three area methods on matched fields via join to fields geom
WITH j AS (SELECT m.field_id, f.geom FROM matched m JOIN fields f ON f.Id=m.field_id)
SELECT
 (SELECT sum(ST_Area(ST_Transform(geom,'EPSG:4326','EPSG:5880')))/10000.0 FROM j) AS ha_5880_proj,
 (SELECT sum(ST_Area_Spheroid(geom))/10000.0 FROM (SELECT geom FROM j)) AS ha_spheroid_default;
SET geometry_always_xy=true;
WITH j AS (SELECT m.field_id, f.geom FROM matched m JOIN fields f ON f.Id=m.field_id)
SELECT (SELECT sum(ST_Area_Spheroid(geom))/10000.0 FROM (SELECT geom FROM j)) AS ha_spheroid_xy;
EOF

cd /workspace
duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -40
LOAD spatial;
SELECT '--- magnitudes vs field_ha ---' t;
SELECT field_id, field_ha,
  deforestarea0104 d0104, deforestarea1520 d1520, deforestarea2124 d2124,
  hansen_covered_area hcov, hansen_loss_area hloss,
  mbcov_area_2024 mbcov, mbvalid_area_2024 mbval
FROM matched WHERE deforestarea2124>0 ORDER BY deforestarea2124 DESC LIMIT 8;
SELECT '--- ranges ---' t;
SELECT max(deforestarea2124), max(field_ha),
       max(deforestarea2124/NULLIF(field_ha,0)) AS max_ratio_2124_to_ha,
       max(hansen_covered_area/NULLIF(field_ha,0)) AS max_hcov_to_ha
FROM matched;
SELECT '--- how many matched have post2020 loss ---' t;
SELECT count(*) FILTER(WHERE deforestarea2124>0) AS n_post2020, count(*) n FROM matched;
EOF

cd /workspace
duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -40
LOAD spatial;
-- add total cleared per field
SELECT '--- mode_year / firstyear sample for loss fields ---' t;
SELECT mode_year, firstyear, firstyearmajority,
       round((deforestarea0104+deforestarea0509+deforestarea1014+deforestarea1520+deforestarea2124)/10000.0,3) tot_clear_ha
FROM matched
WHERE (deforestarea0104+deforestarea0509+deforestarea1014+deforestarea1520+deforestarea2124)>0
ORDER BY tot_clear_ha DESC LIMIT 10;
SELECT '--- q15 headline ---' t;
SELECT 117 AS n_parcels, count(*) AS n_fields, round(sum(field_ha),4) matched_field_ha,
       round(sum(deforestarea2124)/10000.0,6) post2020_loss_ha,
       count(*) FILTER(WHERE deforestarea2124>0) fields_with_post2020_loss
FROM matched;
EOF

cd /workspace
duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -40
LOAD spatial;
-- flagged cadasters: in-scope post-2020 loss > 0
CREATE OR REPLACE TABLE flagged AS
SELECT cod_imovel, sum(post2020_ha) AS post2020_loss_ha
FROM mv WHERE in_scope GROUP BY cod_imovel HAVING sum(post2020_ha)>0;
SELECT count(*) AS n_flagged, sum(post2020_loss_ha) FROM flagged;
-- dominant class per flagged cadaster (by area over ALL matched fields, tie lower mbmode24)
CREATE OR REPLACE TABLE domclass AS
WITH a AS (
  SELECT cod_imovel, CAST(mbmode24 AS INT) mb, sum(field_ha) ha
  FROM mv GROUP BY cod_imovel, CAST(mbmode24 AS INT)),
r AS (SELECT *, row_number() OVER(PARTITION BY cod_imovel ORDER BY ha DESC, mb ASC) rn FROM a)
SELECT cod_imovel, mb AS dominant_mb FROM r WHERE rn=1;
SELECT '--- dominant class distribution among flagged ---' t;
SELECT d.dominant_mb, count(*) n FROM flagged f JOIN domclass d USING(cod_imovel) GROUP BY 1 ORDER BY 1;
EOF

cd /workspace
duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -40
LOAD spatial; SET geometry_always_xy=true;
-- membership rows for our municipios
SELECT '--- membership_muni for our municipios ---' t;
SELECT entity_id, entity_kind, cod_ibge, coop_members, weight, basis, ST_GeometryType(geometry) gt
FROM facilities WHERE tier='membership_muni' AND cod_ibge IN ('5207600','5212204','5219258');
-- facility geom types by tier
SELECT '--- geom types by tier ---' t;
SELECT tier, ST_GeometryType(geometry) gt, count(*) n, min(basis) FROM facilities GROUP BY 1,2 ORDER BY 1;
EOF

cd /workspace
duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -30
LOAD spatial; SET geometry_always_xy=true;
SELECT '--- BR_facilities columns ---' t;
DESCRIBE facilities;
SELECT '--- membership sample ---' t;
SELECT entity_id, entity_kind, tier, weight, basis, geom_method, source FROM facilities WHERE tier='membership_muni' LIMIT 5;
EOF

cd /workspace
duckdb -csv /workspace/work.db <<'EOF' 2>&1 | tail -25
LOAD spatial;
SELECT n.cod_imovel, n.entity_id, n.tier, n.entity_kind, n.basis, round(n.dist_km,3) dist_km
FROM nearest_del n JOIN fcad c USING(cod_imovel)
ORDER BY n.tier, n.dist_km;
SELECT '--- entity_kind of delivery candidates ---' t;
SELECT tier, entity_kind, count(*) FROM nearest_del GROUP BY 1,2;
EOF
